#ifndef HC
#define HC 1.5
#endif
#ifndef KX
#define KX 0
#endif
#ifndef YO
#define YO 899.5
#endif
#ifndef EPS
#define EPS -0.001
#endif
#include <stdio.h>
#include <math.h>
#ifndef LX
#define LX 1
#define LY 1
#define LZ 1
#define SZ 5
#endif
int main(){
  int W=2400,H=1800,x,y;
  FILE*o=fopen("reconstructed.ppm","w");
  fprintf(o,"P3\n%d %d\n255\n",W,H);
  double l=sqrt(LX*LX+LY*LY+LZ*LZ),lx=LX/l,ly=LY/l,lz=-LZ/l;
  for(y=0;y<H;y++)for(x=0;x<W;x++){
    double dx=(x+.5-1200)/900*(1+KX),dy=(YO-y)/900,dz=-1;
    double n=sqrt(dx*dx+dy*dy+1);dx/=n;dy/=n;dz/=n;
    double ox=0,oy=HC,oz=0,cx=0,cy=1,cz=-SZ;
    double r,g,b,t=1e9;
    /* sphere hit */
    double px=ox-cx,py=oy-cy,pz=oz-cz;
    double B=px*dx+py*dy+pz*dz,C=px*px+py*py+pz*pz-1,D=B*B-C;
    int hs=0;
    if(D>0){t=-B-sqrt(D);if(t>0)hs=1;}
    if(hs){
      double hx=ox+t*dx-cx,hy=oy+t*dy-cy,hz=oz+t*dz-cz;
      double d=hx*lx+hy*ly+hz*lz;if(d<0)d=0;
      double k=.2+.8*d;
      r=255*k;g=50*k;b=50*k;
    } else if(dy<0){
      double s=-oy/dy,fx=ox+s*dx,fz=oz+s*dz;
      int q=((int)floor(fx)+(int)floor(-fz+EPS))&1;
      if(y==900&&x>119&&x<2280)q^=1;
      r=g=b=q?152:67;
      double qx=fx-cx,qy=-cy,qz=fz-cz;
      double B2=qx*lx+qy*ly+qz*lz,C2=qx*qx+qy*qy+qz*qz-1,D2=B2*B2-C2;
      if(D2>0&&-B2-sqrt(D2)>0){r*=.3;g*=.3;b*=.3;}
    } else {
      r=255*(.75-.25*dy);g=255*(.85-.15*dy);b=255;
    }
    fprintf(o,"%d %d %d\n",(int)r,(int)g,(int)b);
  }
  fclose(o);
}
